func resolveMatrixPath(workDir, path string) string {
	if filepath.IsAbs(path) {
		return path
	}
	if workDir == "" {
		workDir = "."
	}
	if _, err := os.Stat(path); err == nil {
		return path
	}
	if _, err := os.Stat(filepath.Join(workDir, path)); err == nil {
		return filepath.Join(workDir, path)
	}
	return filepath.Join(workDir, path)
}

